function buildPromptRequest(promptName, rawInput, declaredArgs) {
  const parts = rawInput.split(",").map(s => s.trim());
  const args = {};
  declaredArgs.forEach((argDef, i) => {
    if (parts[i]) args[argDef.name] = parts[i];
  });
  return { name: promptName, arguments: args };
}

def messages_to_llm_input(prompt_messages, existing_history):
    llm_messages = list(existing_history)
    for m in prompt_messages:
        llm_messages.append({
            "role": m["role"],
            "content": m["content"]["text"]
        })
    return llm_messages

