async function runSlashCommand(session, promptName, rawInput, declaredArgs, editText) {
  const args = {};
  rawInput.split(",").map(s => s.trim()).forEach((v, i) => {
    if (declaredArgs[i]) args[declaredArgs[i]] = v;
  });
  const rendered = await session.getPrompt(promptName, args);
  console.log("Preview:", rendered.messages[0].content.text);
  if (editText) rendered.messages[0].content.text += "\n" + editText;
  console.log("Final messages sent to LLM:", rendered.messages);
}
